import sys,json
d=json.load(sys.stdin)
for m in d.get('messages',[]):
    for r in m.get('reactions',[]):
        if r['name']=='eyes' and any(u in r['users'] for u in r.get('users',[])):
            print(m['ts'], m.get('type'), m.get('user'), json.dumps(m.get('text',''))[:120], r['users'])
"

